/// real FFT by Parseval, without the inverse FFT or a separate mean pass.
/// z = ifft(H X), sum_t z_i z_j^* = (1/N) sum_k |H_k|^2 X_i(k) X_j(k)^*, cov = that / N.
/// Mean removal = dropping bin 0.
fn fast_cov(data: &DMatrix<f64>, rfft: &std::sync::Arc<dyn realfft::RealToComplex<f64>>) -> nalgebra::DMatrix<C> {
    let (m, n) = data.shape();
    // one pass: finite check + amax
    let mut amax = 0.0f64;
    for &x in data.iter() { if !x.is_finite() { panic!("nonfinite"); } amax = amax.max(x.abs()); }
    let scale = 1.0 / 2f64.powi(amax.log2().floor() as i32);
    // transpose to contiguous rows (scaled) and FFT each
    let mut specs: Vec<Vec<C>> = Vec::with_capacity(m);
    let mut buf = vec![0.0; n];
    let mut scratch = rfft.make_scratch_vec();
    for r in 0..m {
        for t in 0..n { buf[t] = data[(r, t)] * scale; }
        let mut out = rfft.make_output_vec();
        rfft.process_with_scratch(&mut buf, &mut out, &mut scratch).unwrap();
        specs.push(out);
    }
    let pos_end = n.div_ceil(2); // bins 1..pos_end weight 4; Nyquist (even n) weight 1
    let mut cov = nalgebra::DMatrix::<C>::zeros(m, m);
    for i in 0..m { for j in 0..=i {
        let (a, b) = (&specs[i], &specs[j]);
        let mut s = C::new(0.0, 0.0);
        for k in 1..pos_end { s += a[k] * b[k].conj(); }
        s *= 4.0;
        if n % 2 == 0 { s += a[n / 2] * b[n / 2].conj(); }
        let v = s / (n as f64 * n as f64);
        cov[(i, j)] = v; cov[(j, i)] = v.conj();
    }}
    cov
}

