use std::hint::black_box;
use std::time::Instant;

use musicrs::MusicEstimator;
use nalgebra::{DMatrix, DVector};
use num_complex::Complex;
use rustfft::FftPlanner;

type C = Complex<f64>;

fn read_wav_4ch(path: &str) -> DMatrix<f64> {
    let mut r = hound::WavReader::open(path).unwrap();
    let raw: Vec<i32> = r.samples::<i32>().map(Result::unwrap).collect();
    let s = 2.0_f64.powi(23);
    DMatrix::from_fn(4, raw.len() / 4, |ch, t| raw[t * 4 + ch] as f64 / s)
}

fn time<T>(n: usize, mut f: impl FnMut() -> T) -> f64 {
    for _ in 0..3 { black_box(f()); }
    let mut v: Vec<f64> = (0..n).map(|_| { let t = Instant::now(); black_box(f()); t.elapsed().as_secs_f64() }).collect();
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    v[n / 2] * 1e6 // median, µs
}

fn mean_neumaier(v: &[f64]) -> f64 {
    let (mut s, mut c) = (0.0f64, 0.0f64);
    for &x in v { let t = s + x; c += if s.abs() >= x.abs() { (s - t) + x } else { (x - t) + s }; s = t; }
    (s + c) / v.len() as f64
}

/// Prototype: covariance of the analytic signal of the mean-removed data, computed from the
/// real FFT by Parseval, without the inverse FFT or a separate mean pass.
/// z = ifft(H X), sum_t z_i z_j^* = (1/N) sum_k |H_k|^2 X_i(k) X_j(k)^*, cov = that / N.
/// Mean removal = dropping bin 0.
fn fast_cov(data: &DMatrix<f64>, rfft: &std::sync::Arc<dyn realfft::RealToComplex<f64>>) -> nalgebra::DMatrix<C> {
    let (m, n) = data.shape();
    // one pass: finite check + amax
    let mut amax = 0.0f64;
    for &x in data.iter() { if !x.is_finite() { panic!("nonfinite"); } amax = amax.max(x.abs()); }
    let scale = 1.0 / 2f64.powi(amax.log2().floor() as i32);
    // transpose to contiguous rows (scaled) and FFT each
    let mut specs: Vec<Vec<C>> = Vec::with_capacity(m);
    let mut buf = vec![0.0; n];
    let mut scratch = rfft.make_scratch_vec();
    for r in 0..m {
        for t in 0..n { buf[t] = data[(r, t)] * scale; }
        let mut out = rfft.make_output_vec();
        rfft.process_with_scratch(&mut buf, &mut out, &mut scratch).unwrap();
        specs.push(out);
    }
    let pos_end = n.div_ceil(2); // bins 1..pos_end weight 4; Nyquist (even n) weight 1
    let mut cov = nalgebra::DMatrix::<C>::zeros(m, m);
    for i in 0..m { for j in 0..=i {
        let (a, b) = (&specs[i], &specs[j]);
        let mut s = C::new(0.0, 0.0);
        for k in 1..pos_end { s += a[k] * b[k].conj(); }
        s *= 4.0;
        if n % 2 == 0 { s += a[n / 2] * b[n / 2].conj(); }
        let v = s / (n as f64 * n as f64);
        cov[(i, j)] = v; cov[(j, i)] = v.conj();
    }}
    cov
}

fn main() {
    let est = MusicEstimator::default();
    let iters = 300;
    for dur in ["1.0", "2.0"] {
        let data = read_wav_4ch(&format!("/home/orchid/orca/workspaces/musicrs/check-benchmark/tests/data/single-source/single-source_1400Hz_40deg_{dur}s.wav"));
        let (m, n) = data.shape();
        println!("== {dur} s, {m} x {n}");
        let total = time(iters, || est.estimate_doa_from_real(&data, 1, 1400.0).unwrap());
        println!("{:<44}{:>9.0} µs", "TOTAL estimate_doa_from_real", total);

        // --- stages as in estimate_doa_from_real / estimate_doa ---
        let t_check = time(iters, || data.iter().all(|x| x.is_finite()));
        let t_norm = time(iters, || &data / 2f64.powi(data.amax().log2().floor() as i32));
        let t_mean = time(iters, || {
            let mut acc = 0.0;
            for r in 0..m {
                let row: Vec<f64> = data.row(r).iter().copied().collect();
                let mu = mean_neumaier(&row);
                let c: Vec<f64> = row.iter().map(|x| x - mu).collect();
                acc += data.row(r).norm_squared() + c.iter().map(|x| x * x).sum::<f64>();
            }
            acc
        });
        let rows: Vec<Vec<f64>> = (0..m).map(|r| data.row(r).iter().copied().collect()).collect();
        let t_planner = time(iters, || { let mut p = FftPlanner::<f64>::new(); (p.plan_fft_forward(n), p.plan_fft_inverse(n)) });
        let mut planner = FftPlanner::<f64>::new();
        let fwd = planner.plan_fft_forward(n);
        let inv = planner.plan_fft_inverse(n);
        let t_fft = time(iters, || {
            let mut out = Vec::new();
            for r in &rows {
                let mut s: Vec<C> = r.iter().map(|&x| C::new(x, 0.0)).collect();
                fwd.process(&mut s);
                for x in &mut s[1..n.div_ceil(2)] { *x *= 2.0; }
                for x in &mut s[n / 2 + 1..] { *x = C::new(0.0, 0.0); }
                inv.process(&mut s);
                out.push(s.iter().map(|c| c / n as f64).collect::<Vec<C>>());
            }
            out
        });
        let analytic: Vec<Vec<C>> = rows.iter().map(|r| musicrs::analytic_signal(r)).collect();
        let t_copy = time(iters, || {
            let mut cm = DMatrix::<C>::zeros(m, n);
            for (r, a) in analytic.iter().enumerate() { for (t, &c) in a.iter().enumerate() { cm[(r, t)] = c; } }
            cm
        });
        let cm = DMatrix::from_fn(m, n, |r, t| analytic[r][t]);
        let t_checks2 = time(iters, || {
            let ok = cm.iter().all(|c| c.re.is_finite() && c.im.is_finite());
            let mx = cm.iter().fold(0.0, |a: f64, c| a.max(c.re.abs()).max(c.im.abs()));
            (ok, mx)
        });
        let t_scale = time(iters, || cm.map(|c| c / 1.0));
        let t_cov = time(iters, || (&cm * cm.adjoint()).scale(1.0 / n as f64));
        let t_adj = time(iters, || cm.adjoint());
        let cov = (&cm * cm.adjoint()).scale(1.0 / n as f64);
        let t_eig = time(iters, || est.noise_subspace(&cov, 1).unwrap());
        let nm = est.noise_subspace(&cov, 1).unwrap();
        let t_spec = time(iters, || est.spectrum(&nm, 1400.0).unwrap());
        let stages = [
            ("check finite (real)", t_check), ("normalised_real (copy / scale)", t_norm),
            ("mean, centre, energies (4 rows)", t_mean), ("FftPlanner + 2 plans", t_planner),
            ("Hilbert: complex FFT fwd+inv, 4 rows", t_fft), ("copy into column-major CMatrix", t_copy),
            ("finite + max_abs (complex)", t_checks2), ("scale map (copy)", t_scale),
            ("covariance  (&d * d.adjoint())", t_cov), ("  of which d.adjoint() copy", t_adj),
            ("eig (noise_subspace)", t_eig), ("spectrum (720 angles)", t_spec),
        ];
        let sum: f64 = stages.iter().filter(|s| !s.0.starts_with("  ")).map(|s| s.1).sum();
        for (k, v) in stages { println!("{:<44}{:>9.0} µs  {:>5.1}%", k, v, v / total * 100.0); }
        println!("{:<44}{:>9.0} µs", "sum of stages", sum);

        // --- alternatives ---
        let t_cov_hand = time(iters, || {
            // lower triangle, 10 entries, one pass over samples; rows contiguous
            let mut acc = [[C::new(0.0, 0.0); 4]; 4];
            for t in 0..n {
                let x = [analytic[0][t], analytic[1][t], analytic[2][t], analytic[3][t]];
                for i in 0..4 { for j in 0..=i { acc[i][j] += x[i] * x[j].conj(); } }
            }
            acc
        });
        let mut rp = realfft::RealFftPlanner::<f64>::new();
        let rfwd = rp.plan_fft_forward(n);
        let t_rfft = time(iters, || {
            let mut out = Vec::new();
            for r in &rows {
                let mut inp = r.clone();
                let mut half = rfwd.make_output_vec();
                rfwd.process(&mut inp, &mut half).unwrap();
                let mut s = vec![C::new(0.0, 0.0); n];
                s[0] = half[0];
                for k in 1..n.div_ceil(2) { s[k] = half[k] * 2.0; }
                if n % 2 == 0 { s[n / 2] = half[n / 2]; }
                inv.process(&mut s);
                out.push(s);
            }
            out
        });
        let t_fwd_only = time(iters, || { let mut s: Vec<C> = rows[0].iter().map(|&x| C::new(x, 0.0)).collect(); fwd.process(&mut s); s });
        let t_spec_noalloc = time(iters, || {
            let nh = nm.adjoint();
            let pos = &est.antenna_positions;
            let k = 2.0 * std::f64::consts::PI * 1400.0 / 343.2;
            (0..720).map(|i| {
                let th = i as f64 * std::f64::consts::TAU / 720.0;
                let (s, c) = th.sin_cos();
                let a: [C; 4] = std::array::from_fn(|j| C::from_polar(1.0, k * (pos[j][0] * c + pos[j][1] * s)));
                let mut d = 0.0;
                for r in 0..nh.nrows() { let mut z = C::new(0.0, 0.0); for j in 0..4 { z += nh[(r, j)] * a[j]; } d += z.norm_sqr(); }
                1.0 / d
            }).collect::<Vec<f64>>()
        });
        println!("-- alternatives");
        println!("{:<44}{:>9.0} µs", "covariance, hand-written lower triangle", t_cov_hand);
        println!("{:<44}{:>9.0} µs", "Hilbert with realfft forward, 4 rows", t_rfft);
        println!("{:<44}{:>9.0} µs", "one complex FFT fwd (1 row)", t_fwd_only);
        println!("{:<44}{:>9.0} µs", "spectrum, no per-angle allocation", t_spec_noalloc);
        // --- prototype end to end ---
        let mut rp2 = realfft::RealFftPlanner::<f64>::new();
        let rf = rp2.plan_fft_forward(n);
        let t_fast_cov = time(iters, || fast_cov(&data, &rf));
        let t_fast_total = time(iters, || {
            let cov = fast_cov(&data, &rf);
            let nm = est.noise_subspace(&cov, 1).unwrap();
            let (s, a) = est.spectrum(&nm, 1400.0).unwrap();
            let k = (0..s.len()).fold(0, |b, i| if s[i] > s[b] { i } else { b });
            a[k]
        });
        let t_fast_total_plan = time(iters, || {
            let mut p = realfft::RealFftPlanner::<f64>::new();
            let rf = p.plan_fft_forward(n);
            let cov = fast_cov(&data, &rf);
