            .map(|l| l.split_once(',').unwrap().1.parse().unwrap()).collect()
    }
    fn rel(a: &[f64], b: &[f64]) -> f64 {
        a.iter().zip(b).map(|(s, g)| (s - g).abs() / g.abs()).fold(0.0, f64::max)
