    fn old_cov(data: &DMatrix<f64>) -> CMatrix {
        let an: Vec<Vec<Cplx>> = (0..data.nrows()).map(|m| analytic_signal(&data.row(m).iter().copied().collect::<Vec<_>>())).collect();
        let x = DMatrix::from_fn(data.nrows(), data.ncols(), |m, t| an[m][t]);
