            ("single-source_4700Hz_120deg_1.0s", 4700.0), ("single-source_2500Hz_0deg_2.0s", 2500.0),
            ("single-source_5800Hz_160deg_2.0s", 5800.0), ("single-source_6900Hz_120deg_1.0s", 6900.0),
            ("single-source_3600Hz_0deg_1.0s", 3600.0), ("single-source_3600Hz_40deg_2.0s", 3600.0),
            ("single-source_3600Hz_80deg_1.0s", 3600.0), ("single-source_3600Hz_120deg_2.0s", 3600.0),
            ("single-source_3600Hz_160deg_1.0s", 3600.0), ("single-source_6900Hz_0deg_2.0s", 6900.0),
            ("single-source_6900Hz_40deg_1.0s", 6900.0), ("single-source_6900Hz_80deg_2.0s", 6900.0),
