use std::hint::black_box;
use std::time::Instant;
fn neumaier(v: &[f64]) -> f64 {
    let (mut s, mut c) = (0.0f64, 0.0f64);
    for &x in v { let t = s + x; c += if s.abs() >= x.abs() { (s - t) + x } else { (x - t) + s }; s = t; }
    (s + c) / v.len() as f64
}
fn neumaier4(v: &[f64]) -> f64 {
    // four interleaved compensated sums, combined with Neumaier
    let mut s = [0.0f64; 4]; let mut c = [0.0f64; 4];
    let chunks = v.chunks_exact(4);
    let rest = chunks.remainder();
    for ch in chunks { for i in 0..4 { let x = ch[i]; let t = s[i] + x; c[i] += if s[i].abs() >= x.abs() { (s[i] - t) + x } else { (x - t) + s[i] }; s[i] = t; } }
    let mut all: Vec<f64> = s.iter().chain(c.iter()).copied().chain(rest.iter().copied()).collect();
    all.push(0.0);
    let (mut ss, mut cc) = (0.0f64, 0.0f64);
    for &x in &all { let t = ss + x; cc += if ss.abs() >= x.abs() { (ss - t) + x } else { (x - t) + ss }; ss = t; }
    (ss + cc) / v.len() as f64
}
fn time(f: impl Fn() -> f64) -> f64 { for _ in 0..5 { black_box(f()); } let t = Instant::now(); for _ in 0..500 { black_box(f()); } t.elapsed().as_secs_f64() / 500.0 * 1e6 }
fn main() {
    for n in [16000usize, 32000] {
        let rows: Vec<Vec<f64>> = (0..4).map(|r| (0..n).map(|t| ((t * 7 + r) as f64 * 0.37).sin() * 0.3 + 0.01).collect()).collect();
        let a = time(|| rows.iter().map(|r| neumaier(black_box(r))).sum());
        let b = time(|| rows.iter().map(|r| neumaier4(black_box(r))).sum());
        let e = time(|| rows.iter().map(|r| black_box(r).iter().map(|x| x * x).sum::<f64>()).sum());
        println!("n={n}: neumaier 4 rows {a:.0} µs, 4-way {b:.0} µs, plain sum of squares {e:.0} µs; means equal: {}",
            rows.iter().all(|r| (neumaier(r) - neumaier4(r)).abs() <= f64::EPSILON * neumaier(r).abs()));
    }
}

